`,g.jsxs(i.p,{children:["Most portfolios are flat — scroll, read, scroll, read. Adding 3D elements with ",g.jsx(i.a,{href:"https://docs.pmnd.rs/react-three-fiber",children:"React Three Fiber"})," changes the dynamic entirely. An animated 3D avatar in the hero section immediately tells visitors: ",g.jsx(i.em,{children:"this developer knows more than just CSS"}),"."]}),`
