`,g.jsx(i.p,{children:"The result is a portfolio that feels alive, not static. And that's the whole point."})]})}function AD(n={}){const{wrapper:i}={...qi(),...n.components};return i?g.jsx(i,{...n,children:g.jsx(lv,{...n})}):lv(n)}const CD=Object.freeze(Object.defineProperty({__proto__:null,default:AD,metadata:ED},Symbol.toStringTag,{value:"Module"})),jD={title:"The Physics of Overthinking: Living Inside Your Head and the Cost of Inaction",date:"2026-07-15",excerpt:"An honest observation on how an overactive mind creates a loop of inaction, and why breaking the cycle requires moving out of your head and into reality.",tags:["Personal Growth","Mindset","Mental Health","Reflections"],coverImage:"https://valuehubkenya.co.ke/wp-content/uploads/2026/02/mindset-valuehubkenya.co_.ke1_.jpg"};function rv(n){const i={code:"code",em:"em",h3:"h3",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...qi(),...n.components};return g.jsxs(g.Fragment,{children:[g.jsx("img",{src:"https://valuehubkenya.co.ke/wp-content/uploads/2026/02/mindset-valuehubkenya.co_.ke1_.jpg",alt:"Overthinking and mindset",className:"w-full rounded-xl mb-8"}),`
`,g.jsx(i.p,{children:"I am not writing this as just another casual rant. Instead, these are observations gathered from my daily life—a look into my own perspective on how people think, navigate, and ultimately operate in their lives."}),`
`,g.jsx(i.p,{children:"To be completely honest, I am a deeply negative person. I overthink almost everything. I am constantly plagued by negative thoughts, and for a long time, I have looked at others and assumed they were simply gifted, fortunate, or lucky."}),`
`,g.jsx(i.p,{children:"But while that is how I feel, the observations I make out in the real world tell a completely different story."}),`
`,g.jsx(i.p,{children:"If we look around, the world is simultaneously good and bad. There are people living exceptionally good lives, people who are deeply suffering, and a massive spectrum of individuals living in the gray areas in between. These realities coexist. Life's quality is a vast, continuous spectrum."}),`
`,g.jsxs(i.p,{children:["If you try to find a strict logic behind it, you will quickly find yourself failing to define it within simple ",g.jsx(i.code,{children:"if/else"})," conditions. There are too many variables at play for the human mind to track or control. Luck is not deterministic. Unfortunately, hard work isn't entirely deterministic either."]}),`
`,g.jsx(i.p,{children:"Why do I say that? Because the distribution feels entirely non-linear. There are people who undeniably acquire things effortlessly simply because they were lucky. There are people who fight monumental odds to become who they are or who they want to be. And there are people to whom life just seems fundamentally unfair."}),`
`,g.jsx(i.p,{children:"None of this can be neatly deduced or solved with mathematical equations."}),`
`,g.jsx(i.hr,{}),`
`,g.jsx(i.h3,{children:"The Pattern of Mindset"}),`
`,g.jsxs(i.p,{children:["Despite the chaos, there is one pattern that consistently repeats itself. Whether you look at self-made individuals or those born into highly favorable circumstances, they share a common trait: ",g.jsx(i.strong,{children:"they operate under the assumption that things will work out."})," They give themselves the mental space to breathe, to dream, and to aim high."]}),`
`,g.jsx(i.p,{children:"They rarely visualize worst-case scenarios—unlike me, or unlike people who are going through even tougher times than I am."}),`
`,g.jsx(i.p,{children:"I, on the other hand, think of every single worst-case scenario. And the cruel irony of overthinking is that the more I map out failure, the more I see it manifest into reality."}),`
`,g.jsx(i.p,{children:"I have missed countless opportunities simply because I spent all my energy calculating how I might fail. But by avoiding the opportunity to protect myself, I failed anyway. It is the psychological equivalent of refusing to toss a coin because you are terrified of losing the toss, completely forgetting that there is an equal chance you might actually win."}),`
`,g.jsx(i.hr,{}),`
`,g.jsx(i.h3,{children:"The Hidden Cost of Mental Exhaustion"}),`
`,g.jsxs(i.p,{children:["I have spent a long time asking existential questions. ",g.jsx(i.em,{children:"How could things turn out this way? What did I do to deserve the bad phases I find myself in?"})]}),`
`,g.jsx(i.p,{children:"But looking back, I haven't been entirely honest with myself."}),`
`,g.jsx(i.p,{children:"I was working incredibly hard—but only mentally, never in reality. Every single day felt utterly draining because I was burning massive amounts of cognitive energy simulating outcomes and fearing failures before they even had a chance to occur."}),`
`,g.jsx(i.p,{children:"This heavy mental load translated directly into real-world inaction."}),`
`,g.jsxs(i.ul,{children:[`
`,g.jsxs(i.li,{children:[g.jsx(i.strong,{children:"Not applying for or giving interviews"})," because I assumed I would fail."]}),`
`,g.jsxs(i.li,{children:[g.jsx(i.strong,{children:"Not asking questions or seeking clarity"})," because I was afraid of sounding dumb."]}),`
`,g.jsxs(i.li,{children:[g.jsx(i.strong,{children:"Not tossing the coin"})," because there was a chance of losing."]}),`
`]}),`
`,g.jsx(i.p,{children:"Eventually, this constant state of mental paralysis manifested physically. It turned into deep-seated laziness, which ultimately cascaded into obesity and poor physical health. When you spend all your energy living inside your head, your physical body pays the price."}),`
`,g.jsx(i.hr,{}),`
`,g.jsx(i.h3,{children:"Moving the Needle"}),`
`,g.jsxs(i.p,{children:["The antidote to a fixed, overthinking mindset isn't complicated, though it is incredibly hard to practice: ",g.jsx(i.strong,{children:"a positive mindset, prioritizing action over inaction, and simply keeping moving."})]}),`
`,g.jsx(i.p,{children:'When you force yourself to take action, you break the paralysis. Curiously, the more action you take, the "luckier" you seem to get because you are actually putting yourself in the path of opportunities. Most importantly, physical momentum keeps you fit and grounded, simply because you are finally living in the real world—and no longer trapped inside your head.'})]})}function MD(n={}){const{wrapper:i}={...qi(),...n.components};return i?g.jsx(i,{...n,children:g.jsx(rv,{...n})}):rv(n)}const RD=Object.freeze(Object.defineProperty({__proto__:null,default:MD,metadata:jD},Symbol.toStringTag,{value:"Module"})),DD={title:"Why TypeScript is Worth the Learning Curve",date:"2026-06-15",excerpt:"TypeScript adds complexity, but the payoff in type safety, developer experience, and long-term maintainability makes it indispensable for serious projects.",tags:["TypeScript","JavaScript","DX"]};function ov(n){const i={code:"code",em:"em",h2:"h2",h3:"h3",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...qi(),...n.components};return g.jsxs(g.Fragment,{children:[g.jsxs(i.p,{children:["Every JavaScript developer has asked themselves: ",g.jsx(i.em,{children:"is TypeScript really worth the extra effort?"})," The answer depends on your project, but for anything beyond a quick prototype, the answer is almost always ",g.jsx(i.strong,{children:"yes"}),"."]}),`
`,g.jsx(i.h2,{children:"The Initial Hurdle"}),`
`,g.jsx(i.p,{children:"TypeScript feels slow at first. You're adding types to everything, fighting the compiler, and writing interfaces instead of just hacking code. The learning curve is real — generic types, discriminated unions, and conditional types take time to master."}),`
